css:
.seo-sim-container {
    padding: 28px;
    background: linear-gradient(135deg, #fff5f7 0%, #fef0e6 50%, #fff9e6 100%);
    min-height: 100vh;
    font-family: 'Inter', -apple-system, 'Segoe UI', sans-serif;
    color: #3a2a3f;
}
.seo-sim-header {
    background: linear-gradient(135deg, #c2185b 0%, #f06292 60%, #ff8a65 100%);
    color: #fff;
    border-radius: 22px;
    padding: 32px 36px;
    box-shadow: 0 14px 36px rgba(194,24,91,0.25);
    margin-bottom: 24px;
}
.seo-sim-header h1 {
    font-size: 1.55rem;
    font-weight: 700;
    margin: 0 0 6px 0;
    letter-spacing: 0.01em;
}
.seo-sim-subtitle {
    margin: 0;
    opacity: 0.92;
    font-size: 0.95rem;
}
.seo-sim-period-counter {
    display: flex;
    align-items: center;
    gap: 10px;
    background: #fff;
    border: 2px solid #fbd0dc;
    border-radius: 14px;
    padding: 14px 22px;
    margin-bottom: 22px;
    font-weight: 600;
    color: #880e4f;
    font-size: 1.05rem;
}
.seo-sim-period-counter #currentDay,
.seo-sim-period-counter #maxPeriods {
    color: #c2185b;
    font-size: 1.3rem;
}
.seo-sim-round-name {
    margin-left: auto;
    color: #6d4c41;
    font-style: italic;
    font-weight: 500;
}
.seo-sim-briefing {
    background: #fff;
    border-left: 6px solid #f06292;
    border-radius: 14px;
    padding: 22px 26px;
    margin-bottom: 22px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.05);
}
.seo-sim-briefing h3 {
    color: #c2185b;
    margin: 0 0 10px 0;
    font-size: 1.1rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
}
.seo-sim-briefing div { line-height: 1.55; color: #4a3340; font-size: 0.98rem; }
.seo-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}
.seo-sim-kpi-card {
    background: #fff;
    border-radius: 16px;
    padding: 22px 20px;
    box-shadow: 0 6px 18px rgba(194,24,91,0.08);
    border-top: 4px solid #fbb3c4;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.seo-sim-kpi-card:hover { transform: translateY(-3px); box-shadow: 0 10px 24px rgba(194,24,91,0.15); }
.seo-sim-kpi-card.seo-kpi-primary { border-top-color: #c2185b; background: linear-gradient(180deg,#fff 0%,#fff0f5 100%); }
.seo-sim-kpi-label {
    color: #8a6c74;
    font-size: 0.72rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 10px;
}
.seo-sim-kpi-value {
    font-size: 1.7rem;
    font-weight: 700;
    color: #c2185b;
    letter-spacing: -0.01em;
}
.seo-sim-controls {
    background: #fff;
    border-radius: 18px;
    padding: 28px;
    margin-bottom: 24px;
    box-shadow: 0 8px 22px rgba(194,24,91,0.08);
}
.seo-sim-controls h3 {
    color: #880e4f;
    margin: 0 0 6px 0;
    font-size: 1.15rem;
    font-weight: 700;
}
.seo-sim-hint-text { color: #6d4c41; font-size: 0.9rem; margin-bottom: 18px; }
.seo-sim-controls-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 18px;
    margin-bottom: 18px;
}
.seo-sim-control label {
    display: block;
    font-weight: 600;
    color: #4a2a35;
    margin-bottom: 6px;
    font-size: 0.9rem;
}
.seo-sim-control input[type="number"],
.seo-sim-control select {
    width: 100%;
    padding: 10px 14px;
    border: 2px solid #fbd0dc;
    border-radius: 10px;
    background: #fff9fb;
    color: #3a2a3f;
    font-size: 1rem;
    font-weight: 600;
    transition: border-color 0.2s ease, background 0.2s ease;
}
.seo-sim-control input[type="number"]:focus,
.seo-sim-control select:focus {
    outline: none;
    border-color: #c2185b;
    background: #fff;
}
.seo-sim-control-hint {
    display: block;
    margin-top: 6px;
    color: #8a6c74;
    font-size: 0.78rem;
    line-height: 1.35;
}
.seo-sim-budget-preview {
    background: #fef6e7;
    border: 1.5px dashed #e8a87c;
    border-radius: 10px;
    padding: 12px 16px;
    margin: 10px 0 18px 0;
    color: #6d4c41;
    font-size: 0.92rem;
    font-weight: 500;
}
.seo-sim-budget-preview b { color: #c2185b; }
.seo-sim-actions { display: flex; gap: 12px; flex-wrap: wrap; }
.seo-sim-actions .btn-primary {
    background: linear-gradient(135deg,#c2185b,#f06292);
    border: none;
    padding: 12px 26px;
    font-weight: 700;
    border-radius: 12px;
    letter-spacing: 0.03em;
    box-shadow: 0 6px 18px rgba(194,24,91,0.3);
    transition: transform 0.2s ease;
}
.seo-sim-actions .btn-primary:hover { transform: translateY(-2px); }
.seo-sim-history {
    background: #fff;
    border-radius: 16px;
    padding: 24px;
    margin-bottom: 24px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.05);
}
.seo-sim-history h3 { color: #880e4f; margin: 0 0 14px 0; font-size: 1.05rem; text-transform: uppercase; letter-spacing: 0.08em; }
.seo-sim-history table { font-size: 0.9rem; }
.seo-sim-history th { background: #fce4ec; color: #880e4f; font-weight: 600; }
.seo-sim-charts {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));
    gap: 20px;
    margin-bottom: 24px;
}
.seo-sim-chart-card {
    background: #fff;
    border-radius: 16px;
    padding: 20px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.05);
    height: 320px;
}
@media (max-width: 768px) {
    .seo-sim-container { padding: 16px; }
    .seo-sim-header { padding: 22px; }
    .seo-sim-header h1 { font-size: 1.2rem; }
    .seo-sim-kpi-value { font-size: 1.35rem; }
    .seo-sim-controls-grid { grid-template-columns: 1fr; }
}.seo-sim-container .seo-kpi-score .seo-sim-kpi-value{color:#c2185b}
.seo-sim-container .seo-sim-pace-hint{font-size:.8rem;color:#8a6070;margin-top:6px;line-height:1.45}
.seo-sim-container .seo-sim-budget-preview.is-over{color:#b3261e;font-weight:700}
.seo-sim-container .seo-sim-budget-preview.is-exhausted{color:#6d5a62;font-style:italic}
.seo-sim-container button:focus-visible,.seo-sim-container input:focus-visible,.seo-sim-container select:focus-visible{outline:3px solid #c2185b;outline-offset:2px}
@media (prefers-reduced-motion:reduce){.seo-sim-container *{transition:none!important;animation:none!important}}
@media (max-width:480px){.seo-sim-container .seo-sim-controls-grid{grid-template-columns:1fr}.seo-sim-container .seo-sim-actions .btn{width:100%;margin-bottom:8px}}

