            var ds = sim.state.domainState;
            var sem = this._val('semInput'), seo = this._val('seoInput'), shop = this._val('shoppingInput');
            var tierEl = document.getElementById('tierSelect');
            var tier = (tierEl && tierEl.value) || 'mixed';
            if (TIERS.indexOf(tier) < 0) tier = 'mixed';

            var total = Math.round((sem + seo + shop) * 100) / 100;
            var remaining = ds.budgetRemaining;

            if (total > remaining + 0.001) {
                sim.uiManager.showNotification(
                    this._t('warn_over') + ' COP ' + remaining.toFixed(1) + 'M', 'warning');
                return false;
            }
            if (total <= 0) {
                /* Spending nothing is only a mistake while there is money left.
                   With an exhausted budget the quarter must still be playable —
                   organic traffic from accumulated SEO authority still converts. */
                if (remaining > 0.001) {
                    sim.uiManager.showNotification(this._t('warn_zero'), 'warning');
                    return false;
                }
                sim.uiManager.showNotification(this._t('info_organic_quarter'), 'info');
            }

            decisions.sem = sem;
            decisions.seo = seo;
            decisions.shopping = shop;
            decisions.tier = tier;
            return true;
        }

        /* ------------------------------- model ------------------------------ */

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;

            var tierCPC = { competitive: 3500, mixed: 2350, longtail: 1400 };
            var tierConv = { competitive: 0.020, mixed: 0.025, longtail: 0.038 };
            var aov = 80000;

            var cpc = tierCPC[d.tier] || 2350;
            var convRate = tierConv[d.tier] || 0.025;

            var seasonBoost = 1.0;
            if (round === 3) seasonBoost = 1.25;
            if (round === 4) seasonBoost = 1.40;

            var competitionPenalty = (d.tier === 'competitive' && round >= 2) ? 1.12 : 1.0;
            var effectiveCPC = cpc * competitionPenalty;

            var semClicks = d.sem > 0 ? Math.round((d.sem * 1000000) / effectiveCPC) : 0;
            var semOrders = Math.round(semClicks * convRate * seasonBoost);
            var semRevenue = semOrders * aov;

            var shopCPC = effectiveCPC * 0.75;
            var shopConv = convRate * 1.6;
            var shopClicks = d.shopping > 0 ? Math.round((d.shopping * 1000000) / shopCPC) : 0;
            var shopOrders = Math.round(shopClicks * shopConv * seasonBoost);
            var shopRevenue = shopOrders * aov;

            var i = round - 1;
            var authorityGain = d.seo * 8;

            /* write every series by period index (never push) so an undo + replay
               overwrites the quarter instead of appending a phantom one          */
            ds.authGainHistory[i] = authorityGain; ds.authGainHistory.length = round;
            ds.seoAuthority = this._sum(ds.authGainHistory);

            var organicTraffic = Math.round(ds.seoAuthority * 4 * seasonBoost);
            var organicOrders = Math.round(organicTraffic * 0.032);
            var organicRevenue = organicOrders * aov;

            var periodSpend = Math.round((d.sem + d.seo + d.shopping) * 100) / 100;
            var periodRevenue = semRevenue + shopRevenue + organicRevenue;
            var periodOrders = semOrders + shopOrders + organicOrders;
            var roas = periodSpend > 0 ? periodRevenue / (periodSpend * 1000000) : 0;

            ds.spendHistory[i] = periodSpend; ds.spendHistory.length = round;
            ds.ordersHistory[i] = periodOrders; ds.ordersHistory.length = round;
            ds.revenueHistory[i] = Math.round(periodRevenue); ds.revenueHistory.length = round;
            ds.semRevenueHistory[i] = Math.round(semRevenue); ds.semRevenueHistory.length = round;
            ds.seoRevenueHistory[i] = 0; ds.seoRevenueHistory.length = round;
            ds.shoppingRevenueHistory[i] = Math.round(shopRevenue); ds.shoppingRevenueHistory.length = round;
            ds.organicRevenueHistory[i] = Math.round(organicRevenue); ds.organicRevenueHistory.length = round;
            ds.roasHistory[i] = parseFloat(roas.toFixed(2)); ds.roasHistory.length = round;

            /* cumulative figures are derived, never incremented in place */
            ds.totalSpend = Math.round(this._sum(ds.spendHistory) * 100) / 100;
            ds.totalOrders = this._sum(ds.ordersHistory);
            ds.totalRevenue = this._sum(ds.revenueHistory);
            ds.budgetRemaining = Math.max(0, Math.round((ANNUAL_BUDGET - ds.totalSpend) * 100) / 100);
            ds.lastROAS = roas;

            /* the field express_resolveDomainScore() actually reads */
            var overall = this._composite(ds);
            ds.score = overall;
            ds.performance = {
                overallScore: overall, grade: this._letter(overall),
                roas: parseFloat((ds.totalSpend > 0 ? ds.totalRevenue / (ds.totalSpend * 1000000) : 0).toFixed(2)),
                orders: ds.totalOrders, authority: Math.round(ds.seoAuthority),
                budgetUsed: ds.totalSpend
            };

            var self = this;
            setTimeout(function () {
                self._updateBriefing({ currentPeriod: round + 1 });
                self._renderPreview();
            }, 400);

            return {
                period: round,
                sem_spend: d.sem, seo_spend: d.seo, shop_spend: d.shopping,
                sem_clicks: semClicks, sem_orders: semOrders, sem_revenue: Math.round(semRevenue),
                shop_orders: shopOrders, shop_revenue: Math.round(shopRevenue),
                organic_orders: organicOrders, organic_revenue: Math.round(organicRevenue),
                total_orders: periodOrders, total_revenue: Math.round(periodRevenue),
                roas: parseFloat(roas.toFixed(2)),
                seo_authority: Math.round(ds.seoAuthority),
                overallScore: overall, grade: ds.performance.grade,
                budget_remaining: ds.budgetRemaining,
                tier: d.tier
            };
        }

        _updateBriefing(state) {
            var sim = window.mySimulation;
            var maxP = (sim && sim.state && sim.state.maxPeriods) || 4;
            var ds = (sim && sim.state && sim.state.domainState) || {};
            var p = state.currentPeriod || 1;
            var nameEl = document.getElementById('roundName');
            var briefEl = document.getElementById('briefingText');

            if (p > maxP) {
                var perf = ds.performance || { overallScore: 0, grade: 'F' };
                if (nameEl) nameEl.textContent = this._t('done_name');
                if (briefEl) briefEl.innerHTML = this._fmt(this._t('done_desc'), {
                    score: Math.round(perf.overallScore || 0),
                    grade: perf.grade || 'F',
                    roas: (perf.roas != null ? perf.roas : 0).toFixed ? Number(perf.roas).toFixed(2) : perf.roas,
                    orders: Number(ds.totalOrders || 0).toLocaleString('es-CO'),
                    unspent: Number(ds.budgetRemaining || 0).toFixed(1)
                });
                return;
            }
            var round = this.ROUNDS[Math.min(Math.max(p - 1, 0), this.ROUNDS.length - 1)];
            if (nameEl) nameEl.textContent = this._t(round.nameKey);
            if (briefEl) briefEl.innerHTML = this._t(round.descKey);
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('budgetDisplay', 'domainState.budgetRemaining',
                function(v){ return 'COP ' + Number(v).toFixed(1) + 'M'; });
            uiManager.bind('revenueDisplay', 'domainState.totalRevenue',
                function(v){ return 'COP ' + (Number(v)/1000000).toFixed(1) + 'M'; });
            uiManager.bind('ordersDisplay', 'domainState.totalOrders',
                function(v){ return Number(v).toLocaleString('es-CO'); });
            uiManager.bind('authorityDisplay', 'domainState.seoAuthority',
                function(v){ return Math.round(v); });
            uiManager.bind('roasDisplay', 'domainState.lastROAS',
                function(v){ return Number(v) > 0 ? (Number(v).toFixed(2) + 'x') : '—'; });
            uiManager.bind('scoreDisplay', 'domainState.performance.overallScore',
                function(v){ return Math.round(v || 0) + ' / 100'; });
        }

