        getChartData(state) {
            var ds = state.domainState;
            var labels = (ds.revenueHistory || []).map(function(_, i){ return 'Q' + (i + 1); });
            return {
                revenueChart: { labels: labels, datasets: [{ data: ds.revenueHistory }] },
                channelChart: { labels: labels, datasets: [
                    { data: ds.semRevenueHistory },
                    { data: ds.shoppingRevenueHistory },
                    { data: ds.organicRevenueHistory }
                ] }
            };
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var last = history[history.length - 1] || {};
            var ds = last.domainState || {};
            var r = last.results || {};
            var totalRevenue = ds.totalRevenue != null ? ds.totalRevenue
                : history.reduce(function(s,h){ return s + ((h.results && h.results.total_revenue) || 0); }, 0);
            var totalOrders = ds.totalOrders != null ? ds.totalOrders
                : history.reduce(function(s,h){ return s + ((h.results && h.results.total_orders) || 0); }, 0);
            var totalSpend = ds.totalSpend != null ? ds.totalSpend
                : history.reduce(function(s,h){ var x=h.results||{}; return s + (x.sem_spend||0)+(x.seo_spend||0)+(x.shop_spend||0); }, 0);
            var overallROAS = totalSpend > 0 ? totalRevenue / (totalSpend * 1000000) : 0;
            var overall = (ds.performance && ds.performance.overallScore != null)
                ? ds.performance.overallScore : this._composite({
                    totalRevenue: totalRevenue, totalOrders: totalOrders,
                    totalSpend: totalSpend, seoAuthority: r.seo_authority || 0 });

            var performance = overall >= 85 ? this._t('tier_excellent')
                : overall >= 70 ? this._t('tier_good')
                : overall >= 50 ? this._t('tier_fair') : this._t('tier_beginner');

            var insights = [];
            if (overallROAS < 2) insights.push(this._t('ins_low_roas'));
            else if (overallROAS >= 3) insights.push(this._t('ins_high_roas'));
            else insights.push(this._t('ins_mid_roas'));
            if ((r.seo_authority || 0) > 60) insights.push(this._t('ins_authority_ok'));
            else insights.push(this._t('ins_authority_low'));
            var unspent = ANNUAL_BUDGET - totalSpend;
            if (unspent > 4) insights.push(this._fmt(this._t('ins_unspent'), { unspent: unspent.toFixed(1) }));
            if (r.tier === 'competitive') insights.push(this._t('ins_competitive'));

            return {
                totalScore: overall, overallScore: overall, grade: this._letter(overall),
                totalRevenue: Math.round(totalRevenue), totalOrders: totalOrders,
                overallROAS: parseFloat(overallROAS.toFixed(2)),
                budgetUsed: totalSpend, performance: performance, insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var p = results.period;
            var ds = state.domainState || {};
            if (results.tier === 'competitive' && p >= 2) return this._t('hint_competitive');
            if (results.roas > 0 && results.roas < 1.5 && results.sem_spend > 0) return this._t('hint_low_roas');
            if (ds.seoAuthority < 20 && p >= 2) return this._t('hint_low_seo');
            if (p === 3 && ds.budgetRemaining > 12) return this._t('hint_underspend');
            if (results.roas >= 3) return this._t('hint_scale');
            return null;
        }

